@import "@fontsource-variable/azeret-mono";
@import "@fontsource-variable/figtree";

/* Light (faithful): lavender-white page (#fbf9fe), white panels, violet-black ink (#1a1522),
   electric ultramarine (#2a1eff) for the brand, citron (#eef17c) for one button, soft
   violet (#9b8cf8) for chart lines. */
:root {
  --background: oklch(0.985 0.007 304.2);
  --foreground: oklch(0.208 0.026 301.8);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.208 0.026 301.8);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.208 0.026 301.8);
  --primary: oklch(0.475 0.298 268.6);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.973 0.008 293.9);
  --secondary-foreground: oklch(0.208 0.026 301.8);
  --muted: oklch(0.937 0.004 300);
  --muted-foreground: oklch(0.208 0.026 301.8 / 62%);
  --accent: oklch(0.95 0.025 290.7);
  --accent-foreground: oklch(0.475 0.298 268.6);
  --destructive: oklch(0.56 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.208 0.026 301.8 / 16%);
  --input: oklch(0.208 0.026 301.8 / 16%);
  --ring: oklch(0.475 0.298 268.6);
  --highlight: oklch(0.932 0.14 110.1);
  --highlight-foreground: oklch(0.208 0.026 301.8);
  --glow: oklch(0.699 0.155 287.6);
  --chart-1: oklch(0.475 0.298 268.6);
  --chart-2: oklch(0.521 0 0);
  --chart-3: oklch(0.699 0.155 287.6);
  --chart-4: oklch(0.582 0.127 68.3);
  --chart-5: oklch(0.504 0.108 163.7);
  --sidebar: oklch(0.973 0.008 293.9);
  --sidebar-foreground: oklch(0.208 0.026 301.8);
  --sidebar-primary: oklch(0.475 0.298 268.6);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.95 0.025 290.7);
  --sidebar-accent-foreground: oklch(0.475 0.298 268.6);
  --sidebar-border: oklch(0.208 0.026 301.8 / 16%);
  --sidebar-ring: oklch(0.475 0.298 268.6);

  --typeface-body: "Azeret Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Azeret Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 73.75rem;
  --page-gutter: 1.5rem;
  --section-y: 3.75rem;

  /* Not a token: Azeret Mono sets about 0.1em wider than the original's narrowed mono, so
     the warp blocks subtract this from their letter-spacing. Other themes leave it unset
     (0), and the blocks keep ordinary spacing there. */
  --warp-squeeze: 0.1em;
}

/* Dark sibling: the ink as the page (#120f18), panels a step lighter, lavender-white text,
   a brighter ultramarine so it holds on black, the same citron. */
.dark {
  --background: oklch(0.177 0.019 299.7);
  --foreground: oklch(0.965 0.01 300);
  --card: oklch(0.219 0.024 299.7);
  --card-foreground: oklch(0.965 0.01 300);
  --popover: oklch(0.24 0.026 299.7);
  --popover-foreground: oklch(0.965 0.01 300);
  --primary: oklch(0.591 0.228 279.6);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.205 0.022 299.7);
  --secondary-foreground: oklch(0.965 0.01 300);
  --muted: oklch(0.27 0.022 299.7);
  --muted-foreground: oklch(0.965 0.01 300 / 62%);
  --accent: oklch(0.29 0.07 280);
  --accent-foreground: oklch(0.78 0.12 282);
  --destructive: oklch(0.66 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.965 0.01 300 / 16%);
  --input: oklch(0.965 0.01 300 / 18%);
  --ring: oklch(0.591 0.228 279.6);
  --highlight: oklch(0.932 0.14 110.1);
  --highlight-foreground: oklch(0.208 0.026 301.8);
  --glow: oklch(0.75 0.14 287.6);
  --chart-1: oklch(0.65 0.21 275);
  --chart-2: oklch(0.7 0 0);
  --chart-3: oklch(0.75 0.14 287.6);
  --chart-4: oklch(0.72 0.13 70);
  --chart-5: oklch(0.68 0.12 163.7);
  --sidebar: oklch(0.205 0.022 299.7);
  --sidebar-foreground: oklch(0.965 0.01 300);
  --sidebar-primary: oklch(0.591 0.228 279.6);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.29 0.07 280);
  --sidebar-accent-foreground: oklch(0.78 0.12 282);
  --sidebar-border: oklch(0.965 0.01 300 / 16%);
  --sidebar-ring: oklch(0.591 0.228 279.6);
}
